export const touchUserLastSeenQuery = `-- name: TouchUserLastSeen :exec
WITH membership AS (
	UPDATE "exagram"."memberships" SET last_seen_at = now()
	WHERE user_id = $1 AND workspace_id = $2::uuid AND removed_at IS NULL
	  AND (last_seen_at IS NULL OR last_seen_at < now() - interval '5 minutes')
	RETURNING user_id
)
UPDATE "exagram"."users" SET last_seen_at = now()
WHERE id = $1 AND workspace_id = $2::uuid AND EXISTS (SELECT 1 FROM membership)
  AND (last_seen_at IS NULL OR last_seen_at < now() - interval '5 minutes')`

export interface TouchUserLastSeenArgs {
	id: string
	workspaceId: string
}

export async function touchUserLastSeen(sql: Sql, args: TouchUserLastSeenArgs): Promise<void> {
	await sql.unsafe(touchUserLastSeenQuery, [args.id, args.workspaceId])
}

